/* Тело «Нижний регистр»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nizhniy_registr_body(fl_ctx *ctx, fl_value tekst, fl_value poziciya, fl_value itog, fl_value *result, fl_error *error) {
  for (;;) {
    FL_TRY(fl_tick(ctx, "Нижний регистр", error));
    fl_value fl_t102 = fl_nothing(); /* «длина» */
    FL_TRY(fl_b_dlina(ctx, tekst, &fl_t102, error));
    fl_value fl_t103 = fl_nothing();
    FL_TRY(fl_gt(ctx, poziciya, fl_t102, &fl_t103, error));
    bool fl_t104 = false;
    FL_TRY(fl_cond(ctx, fl_t103, &fl_t104, error));
    if (fl_t104) {
      *result = itog;
      return FL_OK;
    } else {
      fl_value fl_t105 = fl_nothing();
      FL_TRY(fl_add(ctx, poziciya, fl_number(1.0), &fl_t105, error));
      fl_value fl_t106 = fl_nothing(); /* «подстрока» */
      FL_TRY(fl_b_podstroka(ctx, tekst, poziciya, poziciya, &fl_t106, error));
      fl_value fl_t107 = fl_nothing();
      FL_TRY(kompilyator_flang_strochnaya(ctx, fl_t106, &fl_t107, error));
      fl_value fl_t108 = fl_nothing();
      FL_TRY(fl_concat(ctx, itog, fl_t107, &fl_t108, error));
      const fl_value fl_t109 = tekst;
      tekst = fl_t109;
      poziciya = fl_t105;
      itog = fl_t108;
      continue;
    }
  }
}

/*
 * Функция flang «Нижний регистр».
 *
 * Обычная (не тотальная): завершение не доказано, зацикливание не ловится.
 *
 * Хвостовой самовызов развёрнут в цикл: стек не растёт.
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param tekst — «текст»: строка
 * @param poziciya — «позиция»: число
 * @param itog — «итог»: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_nizhniy_registr(fl_ctx *ctx, fl_value tekst, fl_value poziciya, fl_value itog, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Нижний регистр", error));
  {
    const fl_status status = kompilyator_flang_nizhniy_registr_body(ctx, tekst, poziciya, itog, result, error);
    fl_leave(ctx);
    return status;
  }
}

